"""Uncontrolled baseline: no GPU floor, no cap, no battery."""

def control(obs: dict) -> dict[str, float]:
    return {
        "gpu_floor_mw": 0.0,
        "gpu_cap_mw": float(obs["rated_mw"]),
        "battery_setpoint_mw": 0.0,
    }

b1.code:
