def control(obs: dict) -> dict[str, float]:
    rated = float(obs["rated_mw"])
    return {
        "gpu_floor_mw": 0.90 * rated,
        "gpu_cap_mw": rated,
        "battery_setpoint_mw": 0.0,
    }

